export function dutreilSvg(lang, kind, mobile = false) {
  if (lang !== 'fr' && lang !== 'en') throw new TypeError('Invalid Dutreil language');
  if (typeof kind !== 'string' || !kinds.includes(kind)) throw new TypeError('Invalid Dutreil kind');
  if (typeof mobile !== 'boolean') throw new TypeError('Invalid Dutreil mobile flag');
  return figures[lang][kind + (mobile ? '-mobile' : '')];
}

export function validateDutreilFigure(props) {
  if (!props || typeof props !== 'object' || Array.isArray(props)) throw new TypeError('Invalid Dutreil props');
  const { lang = 'fr', kind, number, caption, sources } = props;
  if (lang !== 'fr' && lang !== 'en') throw new TypeError('Invalid Dutreil language');
  if (typeof kind !== 'string' || !kinds.includes(kind)) throw new TypeError('Invalid Dutreil kind');
  if (typeof number !== 'string' || !/^0?[1-6]$/.test(number) || Number(number) !== kinds.indexOf(kind) + 1) throw new TypeError('Invalid Dutreil figure number');
  if (typeof caption !== 'string' || !caption.trim()) throw new TypeError('Invalid Dutreil caption');
  if (typeof sources !== 'string') throw new TypeError('Invalid Dutreil sources');
  const references = sources.trim().split(/\s+/);
  if (!references.length || references.some(id => !/^[1-9]\d?$/.test(id)) || new Set(references).size !== references.length) throw new TypeError('Invalid Dutreil sources');
  return { lang, kind, number: number.padStart(2, '0'), caption, references };
}
